// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of knuckle segments
knuckle_pitch = plate_len / knuckle_n; // 12 mm spacing
knuckle_z   = 3;     // knuckle axis height above bed
knuckle_y   = plate_wid / 2; // 15 mm (on +Y edge)

// ---- Pin hole ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X (1st, 3rd, 5th segments)
        for (i = [0 : 2 : knuckle_n - 1]) {
            x_c = -plate_len/2 + (i + 1) * knuckle_pitch;
            translate([x_c - knuckle_d/2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps);
        }
    }

    // Pin hole through every knuckle along the common axis
    for (i = [0 : 2 : knuckle_n - 1]) {
        x_c = -plate_len/2 + (i + 1) * knuckle_pitch;
        translate([x_c, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2*eps);
    }
}
